import { gs, GlideDateTime } from '@servicenow/glide'

export function setComplaintDefaults(current, previous) {
  // Auto-generate complaint number if not set
  if (gs.nil(current.getValue('complaint_number'))) {
    current.setValue('complaint_number', gs.generateGUID())
  }

  // Set reported date to current time if not set
  if (gs.nil(current.getValue('sys_created_on'))) {
    const now = new GlideDateTime()
    current.setValue('sys_created_on', now.getDisplayValue())
  }

  // If complainant chooses to be anonymous, clear personal info
  if (current.getValue('is_anonymous') === 'true') {
    current.setValue('complainant_email', '')
    current.setValue('complainant_phone', '')
    current.setValue('complainant_name', 'Anonymous')
  }

  // Auto-set priority based on severity and complaint type
  const severityLevel = current.getValue('severity_level')
  const complaintType = current.getValue('complaint_type')

  if (severityLevel === 'life_threatening' || 
      (complaintType === 'reckless_driving' && severityLevel === 'severe')) {
    current.setValue('priority', 'critical')
  } else if (severityLevel === 'severe') {
    current.setValue('priority', 'high')
  } else if (severityLevel === 'moderate') {
    current.setValue('priority', 'medium')
  } else {
    current.setValue('priority', 'low')
  }

  gs.addInfoMessage('Road safety complaint has been submitted successfully. Complaint number: ' + current.getValue('complaint_number'))
}
